import math
import sys

def main():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    if n > 11:
        print(0)
        return

    class Point:
        def __init__(self, v, w, x, y, z):
            self.v = v
            self.w = w
            self.x = x
            self.y = y
            self.z = z

        def mag(self):
            return math.sqrt(self.v ** 2 + self.w ** 2 + self.x ** 2 + self.y ** 2 + self.z ** 2)

    points = []
    for i in range(1, n + 1):
        a, b, c, d, e = map(int, input[i].split())
        points.append(Point(a, b, c, d, e))

    def angle(a, b):
        amag = a.mag()
        bmag = b.mag()
        abmag = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z
        # To avoid floating point errors, clip the value between -1 and 1
        cosine_value = abmag / (amag * bmag) if amag != 0 and bmag != 0 else 1
        cosine_value = max(min(cosine_value, 1), -1)
        return math.degrees(math.acos(cosine_value)) < 90

    good_indices = set()
    for i in range(n):
        is_good = True
        for j in range(n):
            for k in range(n):
                if i != j and i != k and j != k:
                    one = points[j]
                    two = points[k]
                    three = points[i]
                    lol2 = Point(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z)
                    lol1 = Point(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z)
                    if angle(lol1, lol2):
                        is_good = False
        if is_good:
            good_indices.add(i + 1)

    if not good_indices:
        print(0)
    else:
        print(len(good_indices))
        for idx in sorted(good_indices):
            print(idx)

if __name__ == "__main__":
    main()

